private static boolean isMatchingExecutable(final Executable method, final Class<?>[] parameterTypes) {
    final Class<?>[] methodParameterTypes = method.getParameterTypes();
    if (method.isVarArgs()) {
        int methodParameterCount = methodParameterTypes.length - 1; // Number of parameters before the varargs parameter
        if (parameterTypes.length < methodParameterCount) {
            return false;
        }

        // Check non-varargs parameters
        for (int i = 0; i < methodParameterCount; i++) {
            if (!ClassUtils.isAssignable(parameterTypes[i], methodParameterTypes[i], true)) {
                return false;
            }
        }

        // Check varargs parameter
        final Class<?> varArgParameterType = methodParameterTypes[methodParameterCount].getComponentType();
        for (int i = methodParameterCount; i < parameterTypes.length; i++) {
            if (!ClassUtils.isAssignable(parameterTypes[i], varArgParameterType, true)) {
                return false;
            }
        }

        return true;
    }

    // Not a varargs method, check all parameters
    if (parameterTypes.length != methodParameterTypes.length) {
        return false;
    }

    return ClassUtils.isAssignable(parameterTypes, methodParameterTypes, true);
}

